import{az as s,P as t,Q as l,aQ as n}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"server/base/DNS.md","filePath":"server/base/DNS.md","lastUpdated":1785339991000}'),e={name:"server/base/DNS.md"};function o(p,a,c,d,r,i){return t(),l("div",null,[...a[0]||(a[0]=[n(`<h2 id="dns-域名系统" tabindex="-1">DNS 域名系统 <a class="header-anchor" href="#dns-域名系统" aria-label="Permalink to “DNS 域名系统”">​</a></h2><p><a href="https://developer.mozilla.org/zh-CN/docs/Glossary/DNS" target="_blank" rel="noreferrer">MDN DNS</a></p><p>DNS（Domain Name System）是互联网的&quot;电话簿&quot;，负责将人类可读的域名（如 <code>www.example.com</code>）解析为机器可识别的 IP 地址（如 <code>93.184.216.34</code>）。没有 DNS，用户需要记住一串数字才能访问网站。</p><h2 id="dns-解析过程" tabindex="-1">DNS 解析过程 <a class="header-anchor" href="#dns-解析过程" aria-label="Permalink to “DNS 解析过程”">​</a></h2><p>一次完整的 DNS 解析涉及多个层级的服务器协作。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 浏览器访问 www.example.com 的解析流程</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. 浏览器缓存：先查浏览器自身的 DNS 缓存</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. 操作系统缓存：再查 OS 的 DNS 缓存（hosts 文件）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 本地 DNS 服务器（递归解析器）：向 ISP 的 DNS 发起查询</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. 根域名服务器：返回 .com 顶级域服务器地址</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 5. 顶级域名服务器（TLD）：返回 example.com 权威服务器地址</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 6. 权威域名服务器：返回 www.example.com 的 IP 地址</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 7. 本地 DNS 缓存结果并返回给客户端</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 使用 dig 查看解析过程</span></span>
<span class="line"><span style="color:#FFCB6B;">dig</span><span style="color:#C3E88D;"> +trace</span><span style="color:#C3E88D;"> www.example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 查询指定记录</span></span>
<span class="line"><span style="color:#FFCB6B;">dig</span><span style="color:#C3E88D;"> www.example.com</span><span style="color:#C3E88D;"> A</span></span>
<span class="line"><span style="color:#FFCB6B;">dig</span><span style="color:#C3E88D;"> example.com</span><span style="color:#C3E88D;"> NS</span></span>
<span class="line"><span style="color:#FFCB6B;">dig</span><span style="color:#C3E88D;"> example.com</span><span style="color:#C3E88D;"> MX</span></span></code></pre></div><h2 id="解析流程对比" tabindex="-1">解析流程对比 <a class="header-anchor" href="#解析流程对比" aria-label="Permalink to “解析流程对比”">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>查询对象</th><th>返回结果</th></tr></thead><tbody><tr><td>1</td><td>浏览器/OS 缓存</td><td>命中则直接返回</td></tr><tr><td>2</td><td>本地 DNS 服务器</td><td>命中缓存则返回</td></tr><tr><td>3</td><td>根域名服务器</td><td>TLD 服务器地址</td></tr><tr><td>4</td><td>顶级域名服务器</td><td>权威服务器地址</td></tr><tr><td>5</td><td>权威域名服务器</td><td>最终 IP 地址</td></tr></tbody></table><h2 id="dns-记录类型" tabindex="-1">DNS 记录类型 <a class="header-anchor" href="#dns-记录类型" aria-label="Permalink to “DNS 记录类型”">​</a></h2><table tabindex="0"><thead><tr><th>记录类型</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td>A</td><td>域名 -&gt; IPv4</td><td><code>example.com. A 93.184.216.34</code></td></tr><tr><td>AAAA</td><td>域名 -&gt; IPv6</td><td><code>example.com. AAAA 2606:2800:220:1::</code></td></tr><tr><td>CNAME</td><td>别名指向另一个域名</td><td><code>www.example.com CNAME example.com</code></td></tr><tr><td>MX</td><td>邮件交换服务器</td><td><code>example.com MX 10 mail.example.com</code></td></tr><tr><td>NS</td><td>域名的权威服务器</td><td><code>example.com NS ns1.example.com</code></td></tr><tr><td>TXT</td><td>文本记录（SPF/验证）</td><td><code>example.com TXT &quot;v=spf1 -all&quot;</code></td></tr><tr><td>SRV</td><td>服务记录</td><td><code>_sip._tcp.example.com SRV 10 60 5060 sip.example.com</code></td></tr></tbody></table><h2 id="递归查询与迭代查询" tabindex="-1">递归查询与迭代查询 <a class="header-anchor" href="#递归查询与迭代查询" aria-label="Permalink to “递归查询与迭代查询”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 递归查询：客户端 -&gt; 本地 DNS</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#   客户端只需发一次请求，本地 DNS 负责后续所有查询</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#   &quot;你帮我把结果找出来&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 迭代查询：本地 DNS -&gt; 根/TLD/权威服务器</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#   每一级服务器只返回下一级地址，不代为查询</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#   &quot;我不知道，但你可以去问 XXX&quot;</span></span></code></pre></div><h2 id="dns-缓存与-ttl" tabindex="-1">DNS 缓存与 TTL <a class="header-anchor" href="#dns-缓存与-ttl" aria-label="Permalink to “DNS 缓存与 TTL”">​</a></h2><p>DNS 记录携带 TTL（Time To Live）值，决定缓存有效时长。TTL 越大，解析越快但变更生效越慢。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 设置 TTL</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># www.example.com.  3600  IN  A  93.184.216.34</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#                    ↑</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#               TTL=3600 秒（1 小时）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>TTL 策略</th><th>TTL 值</th><th>适用场景</th></tr></thead><tbody><tr><td>短 TTL</td><td>60-300 秒</td><td>即将迁移、灰度发布</td></tr><tr><td>中 TTL</td><td>3600 秒</td><td>日常使用</td></tr><tr><td>长 TTL</td><td>86400 秒</td><td>稳定不变的记录</td></tr></tbody></table><h2 id="基于-dns-的负载均衡" tabindex="-1">基于 DNS 的负载均衡 <a class="header-anchor" href="#基于-dns-的负载均衡" aria-label="Permalink to “基于 DNS 的负载均衡”">​</a></h2><p>通过为一个域名配置多个 A 记录，DNS 服务器轮询返回不同 IP，实现简单的负载分发。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 配置多个 A 记录</span></span>
<span class="line"><span style="color:#FFCB6B;">www.example.com.</span><span style="color:#F78C6C;">  300</span><span style="color:#C3E88D;">  IN</span><span style="color:#C3E88D;">  A</span><span style="color:#F78C6C;">  192.168.1.1</span></span>
<span class="line"><span style="color:#FFCB6B;">www.example.com.</span><span style="color:#F78C6C;">  300</span><span style="color:#C3E88D;">  IN</span><span style="color:#C3E88D;">  A</span><span style="color:#F78C6C;">  192.168.1.2</span></span>
<span class="line"><span style="color:#FFCB6B;">www.example.com.</span><span style="color:#F78C6C;">  300</span><span style="color:#C3E88D;">  IN</span><span style="color:#C3E88D;">  A</span><span style="color:#F78C6C;">  192.168.1.3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 客户端每次解析可能获得不同 IP，流量被分散到多台服务器</span></span></code></pre></div><p>DNS 是互联网的基础设施，其解析效率与可靠性直接影响用户体验。合理设置 TTL、利用多级缓存和负载均衡，可以提升域名解析的性能与可用性。</p>`,21)])])}const b=s(e,[["render",o]]);export{m as __pageData,b as default};
